import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`personal-brand-strategy`,heroTitle:`Build your personal brand strategy in minutes`,heroSubtitle:`Perplexity Computer audits your online presence, analyzes your positioning, and delivers a complete personal brand playbook — automatically.`,inputUrlCta:`Audit my brand`,inputUrlPlaceholder:`linkedin.com/in/yourname`,inputUrlPrefill:`Go to {url} and perform a comprehensive personal brand audit. 1) Analyze the person's current positioning — bio, messaging, tone of voice, visual identity, and key topics they're known for. 2) Search across LinkedIn, Twitter/X, and Google to assess their digital footprint, authority signals, and content consistency. 3) Identify 5 direct competitors or peers in their space and compare positioning, audience engagement, and content strategy. 4) Score their personal brand across five dimensions: clarity, consistency, authority, visibility, and differentiation. 5) Deliver a complete personal brand strategy with: a refined positioning statement, 3 content pillars with topic ideas, a recommended posting cadence per platform, bio and headline rewrites for LinkedIn and Twitter/X, and a 90-day action plan to grow visibility and authority in their niche.`,heroOverlaySteps:[`Analyzing your online presence and current positioning`,`Researching competitors and peers in your space`,`Scoring your brand across clarity, authority, and visibility`,`Personal brand strategy and 90-day action plan — ready to execute`],generatingSteps:[`Visiting {url} to extract your positioning, messaging, and content footprint`,`Designing an agent to benchmark your brand against peers and competitors`,`Configuring brand scoring across clarity, consistency, authority, visibility, and differentiation`,`Setting up your personal brand playbook with content pillars and a 90-day plan`],featureSectionTitle:`From profile to personal brand playbook`,featureCardTitles:[`Connects to your content stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Notion, Google Docs, Google Sheets, Canva, Slack — Computer delivers your brand strategy and content calendar straight into the tools you already use.`,`Brand positioning statement. Competitor benchmarks. Content pillars with topic ideas. Bio and headline rewrites. A 90-day action plan to grow your authority.`],capabilitySectionTitle:`Your brand strategist, on autopilot`,capabilitySectionSubtitle:`Paste your profile, step away, come back to a complete personal brand strategy.`,capabilityCards:[{title:`Brand Audit`,description:`Computer can analyze your profiles across LinkedIn, Twitter/X, and Google — and score your positioning on clarity, consistency, and differentiation.`},{title:`Competitor Analysis`,description:`Computer can identify peers in your niche and benchmark their content strategy, audience engagement, and authority signals against yours.`},{title:`Strategy Playbook`,description:`Computer can build a complete brand strategy — positioning statement, content pillars, platform-specific tactics, and a 90-day growth plan.`},{title:`Connect Your Tools`,description:`Computer can push your strategy into Notion, Google Docs, Google Sheets, and Canva — build workflows across your entire content and planning stack.`},{title:`Remember & Refine`,description:`Computer can remember your brand guidelines, past strategies, and growth metrics across sessions — so every update builds on what's working.`},{title:`Monitor & Alert`,description:`Computer can track your online visibility weekly and flag when competitors shift positioning or new opportunities to grow your authority appear.`}]});export{t as default};
